void bucket_add_partition_point(std::vector<float>& hash_points, float point) {
    // Find the position where the point should be inserted to maintain sorted order
    for (auto it = hash_points.begin(); it != hash_points.end(); ++it) {
        if (*it > point) {
            hash_points.insert(it, point);
            return;
        }
    }
    // If we reach here, the point should be inserted at the end
    hash_points.push_back(point);
}

